<?php
session(); include('../include/config.php'); require_once __DIR__.'/module_bootstrap.php'; hms_module_require_roles(array('admin','doctor','perawat'));
if($_SERVER['REQUEST_METHOD']==='POST'){ hms_module_csrf(); $action=$_POST['action']??'';
 if($action==='bed'){ $room=trim($_POST['room_no']??'');$bed=trim($_POST['bed_no']??'');$class=trim($_POST['class_name']??'');$ward=trim($_POST['ward']??'');$rate=max(0,(float)($_POST['daily_rate']??0)); if($room&&$bed&&$class&&$ward){$st=mysqli_prepare($con,'INSERT INTO hms_beds(room_no,bed_no,class_name,ward,daily_rate) VALUES(?,?,?,?,?)'); if($st){mysqli_stmt_bind_param($st,'ssssd',$room,$bed,$class,$ward,$rate);if(mysqli_stmt_execute($st)){hms_module_audit($con,'CREATE','RAWAT_INAP','hms_beds',mysqli_insert_id($con),'Bed ditambahkan',null,array('room_no'=>$room,'bed_no'=>$bed,'ward'=>$ward,'class_name'=>$class));hms_set_flash('success','Tempat tidur ditambahkan.');}else hms_set_flash('danger','Bed sudah ada atau gagal disimpan.');mysqli_stmt_close($st);}}}
 if($action==='admit'){ $pid=(int)($_POST['patient_id']??0);$visit=(int)($_POST['visit_id']??0);$bed=(int)($_POST['bed_id']??0);$doc=(int)($_POST['doctor_id']??0);$class=trim($_POST['class_name']??''); if($pid>0&&$bed>0){ mysqli_begin_transaction($con); try { $bedRow=hms_fetch_one($con,'SELECT * FROM hms_beds WHERE id=? FOR UPDATE','i',array($bed)); if(!$bedRow||$bedRow['status']!=='TERSEDIA') throw new RuntimeException('Bed sudah tidak tersedia.'); $active=hms_scalar($con,"SELECT COUNT(*) FROM hms_admissions WHERE patient_id=? AND status='DIRAWAT'",'i',array($pid)); if((int)$active>0) throw new RuntimeException('Pasien masih memiliki admission aktif.'); if($visit>0){$vr=hms_fetch_one($con,'SELECT patient_id,status FROM hms_patient_visits WHERE id=? FOR UPDATE','i',array($visit));if(!$vr||((int)$vr['patient_id']!==$pid))throw new RuntimeException('Kunjungan tidak sesuai dengan pasien.');}
 $code=hms_module_next_code($con,'hms_admissions','ADM','id'); $st=mysqli_prepare($con,'INSERT INTO hms_admissions(visit_id,patient_id,admission_no,bed_id,class_name,attending_doctor_id) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($st,'iisisi',$visit,$pid,$code,$bed,$class,$doc);if(!mysqli_stmt_execute($st))throw new RuntimeException('Admission gagal.');$aid=mysqli_stmt_insert_id($st);mysqli_stmt_close($st);$locked=hms_execute($con,"UPDATE hms_beds SET status='TERISI' WHERE id=? AND status='TERSEDIA'",'i',array($bed));if($locked!==1)throw new RuntimeException('Bed gagal dikunci.');
 if($visit>0) hms_execute($con,"UPDATE hms_patient_visits SET status='DILAYANI',doctor_id=IF(? > 0,?,doctor_id),updated_at=NOW() WHERE id=?",'iii',array($doc,$doc,$visit));
 $igd=hms_fetch_one($con,"SELECT id FROM hms_igd_visits WHERE visit_id=? AND disposition='RAWAT_INAP' AND status='AKTIF' ORDER BY id DESC LIMIT 1 FOR UPDATE",'i',array($visit)); if($igd){hms_execute($con,"UPDATE hms_igd_visits SET admission_id=?,status='SELESAI' WHERE id=?",'ii',array($aid,$igd['id']));}
 mysqli_commit($con);hms_module_workflow_event($con,$pid,$visit?:null,$aid,$igd['id']??null,'ADMISSION','DIRAWAT','Pasien masuk rawat inap.');hms_module_audit($con,'CREATE','RAWAT_INAP','hms_admissions',$aid,'Admission dibuat',null,array('patient_id'=>$pid,'visit_id'=>$visit,'bed_id'=>$bed,'admission_no'=>$code));hms_set_flash('success','Admission tersimpan: '.$code);} catch(Throwable $e){mysqli_rollback($con);hms_set_flash('danger',$e->getMessage());}}
 }
 if($action==='discharge'){ $aid=(int)($_POST['admission_id']??0);$note=trim($_POST['discharge_note']??''); if($aid>0){mysqli_begin_transaction($con);try{$row=hms_fetch_one($con,"SELECT a.*,b.daily_rate,b.room_no,b.bed_no FROM hms_admissions a LEFT JOIN hms_beds b ON b.id=a.bed_id WHERE a.id=? AND a.status='DIRAWAT' FOR UPDATE",'i',array($aid));if(!$row)throw new RuntimeException('Admission aktif tidak ditemukan.');hms_execute($con,"UPDATE hms_admissions SET status='PULANG',discharge_date=NOW(),discharge_note=? WHERE id=?",'si',array($note,$aid));if(!empty($row['bed_id']))hms_execute($con,"UPDATE hms_beds SET status='TERSEDIA' WHERE id=? AND status='TERISI'",'i',array((int)$row['bed_id']));if(!empty($row['visit_id']))hms_execute($con,"UPDATE hms_patient_visits SET status='SELESAI',updated_at=NOW() WHERE id=?",'i',array((int)$row['visit_id']));mysqli_commit($con);$days=max(1,(int)hms_scalar($con,'SELECT TIMESTAMPDIFF(DAY,admission_date,discharge_date)+1 FROM hms_admissions WHERE id=?','i',array($aid)));$rate=(float)($row['daily_rate']??0);if($rate>0){try{hms_module_post_charge($con,(int)$row['patient_id'],(int)($row['visit_id']?:0),$aid,null,null,null,'KAMAR','Kamar '.$row['room_no'].'-'.$row['bed_no'].' ('.$days.' hari)',$days,$rate);}catch(Throwable $ce){hms_set_flash('warning','Pasien sudah dipulangkan, tetapi billing kamar gagal: '.$ce->getMessage());}}hms_module_workflow_event($con,(int)$row['patient_id'],$row['visit_id']?:null,$aid,null,'DISCHARGE','PULANG','Pasien dipulangkan dari rawat inap.');hms_module_audit($con,'DISCHARGE','RAWAT_INAP','hms_admissions',$aid,'Pasien dipulangkan',$row,array('status'=>'PULANG','discharge_note'=>$note,'days'=>$days));hms_set_flash('success','Pasien dipulangkan dan bed dikosongkan.');}catch(Throwable $e){mysqli_rollback($con);hms_set_flash('danger',$e->getMessage());}}}
 if($action==='transfer'){ $aid=(int)($_POST['admission_id']??0);$newBed=(int)($_POST['new_bed_id']??0); if($aid>0&&$newBed>0){mysqli_begin_transaction($con);try{$row=hms_fetch_one($con,"SELECT * FROM hms_admissions WHERE id=? AND status='DIRAWAT' FOR UPDATE",'i',array($aid));$nb=hms_fetch_one($con,"SELECT * FROM hms_beds WHERE id=? FOR UPDATE",'i',array($newBed));if(!$row||!$nb||$nb['status']!=='TERSEDIA')throw new RuntimeException('Admission atau bed tujuan tidak tersedia.');$old=(int)$row['bed_id'];if($old===$newBed)throw new RuntimeException('Bed tujuan sama dengan bed saat ini.');hms_execute($con,'UPDATE hms_admissions SET bed_id=?,status=\'DIRAWAT\' WHERE id=?','ii',array($newBed,$aid));hms_execute($con,'INSERT INTO hms_bed_movements(admission_id,from_bed_id,to_bed_id,reason) VALUES(?,?,?,?)','iiis',array($aid,$old,$newBed,'Mutasi internal'));if($old)hms_execute($con,"UPDATE hms_beds SET status='TERSEDIA' WHERE id=?",'i',array($old));hms_execute($con,"UPDATE hms_beds SET status='TERISI' WHERE id=? AND status='TERSEDIA'",'i',array($newBed));if(mysqli_affected_rows($con)!==1)throw new RuntimeException('Bed tujuan gagal dikunci.');mysqli_commit($con);hms_module_workflow_event($con,(int)$row['patient_id'],(int)($row['visit_id']??0),$aid,null,'BED_TRANSFER','SELESAI','Pasien dipindahkan ke bed baru.');hms_module_audit($con,'TRANSFER','RAWAT_INAP','hms_admissions',$aid,'Mutasi bed',array('bed_id'=>$old),array('bed_id'=>$newBed));hms_set_flash('success','Mutasi bed berhasil.');}catch(Throwable $e){mysqli_rollback($con);hms_set_flash('danger',$e->getMessage());}}}
}
$beds=hms_fetch_all($con,'SELECT * FROM hms_beds ORDER BY ward,room_no,bed_no');$visits=hms_fetch_all($con,"SELECT id,registration_no,patient_id,visit_type,visit_date FROM hms_patient_visits WHERE status IN ('MENUNGGU','DILAYANI') ORDER BY id DESC LIMIT 300");$patients=hms_fetch_all($con,'SELECT ID,PatientName FROM tblpatient ORDER BY PatientName LIMIT 300');$doctors=hms_fetch_all($con,'SELECT id,doctorName FROM doctors ORDER BY doctorName');$adms=hms_fetch_all($con,'SELECT a.*,p.PatientName,b.room_no,b.bed_no,b.ward,d.doctorName FROM hms_admissions a LEFT JOIN tblpatient p ON p.ID=a.patient_id LEFT JOIN hms_beds b ON b.id=a.bed_id LEFT JOIN doctors d ON d.id=a.attending_doctor_id ORDER BY a.id DESC LIMIT 100');
$role=hms_module_current_role(); hms_layout_header('Rawat Inap & Bed Management',$role,'operations');
?>
<div class="hms-page-title"><div><h1>Rawat Inap & Bed Management</h1><div class="text-muted">Admission, alokasi tempat tidur, mutasi dan discharge.</div></div></div>
<div class="row g-3 mb-4"><div class="col-lg-5"><div class="hms-card p-3"><h2 class="h5">Tambah Tempat Tidur</h2><form method="post"><?php echo hms_csrf_field(); ?><input type="hidden" name="action" value="bed"><div class="row g-2"><div class="col-6"><input name="ward" class="form-control" placeholder="Bangsal" required></div><div class="col-6"><input name="class_name" class="form-control" placeholder="Kelas" required></div><div class="col-6"><input name="room_no" class="form-control" placeholder="Kamar" required></div><div class="col-6"><input name="bed_no" class="form-control" placeholder="Bed" required></div><div class="col-6"><input name="daily_rate" type="number" min="0" step="0.01" class="form-control" placeholder="Tarif/hari"></div><div class="col-6"><button class="btn btn-primary w-100">Simpan Bed</button></div></div></form></div></div>
<div class="col-lg-7"><div class="hms-card p-3"><h2 class="h5">Admission</h2><form method="post" class="row g-2"><?php echo hms_csrf_field(); ?><input type="hidden" name="action" value="admit"><div class="col-md-3"><select name="patient_id" class="form-select" required><option value="">Pasien</option><?php foreach($patients as $p){ ?><option value="<?php echo (int)$p['ID']; ?>"><?php echo hms_e($p['PatientName']); ?></option><?php } ?></select></div><div class="col-md-3"><select name="visit_id" class="form-select"><option value="0">Kunjungan / IGD</option><?php foreach($visits as $v){ ?><option value="<?php echo (int)$v['id']; ?>"><?php echo hms_e($v['registration_no'].' / '.$v['visit_type'].' / '.$v['visit_date']); ?></option><?php } ?></select></div><div class="col-md-3"><select name="bed_id" class="form-select" required><option value="">Bed tersedia</option><?php foreach($beds as $b){ if($b['status']==='TERSEDIA'){ ?><option value="<?php echo (int)$b['id']; ?>"><?php echo hms_e($b['ward'].' / '.$b['room_no'].'-'.$b['bed_no'].' / '.$b['class_name']); ?></option><?php }} ?></select></div><div class="col-md-3"><select name="doctor_id" class="form-select"><option value="0">Dokter</option><?php foreach($doctors as $d){ ?><option value="<?php echo (int)$d['id']; ?>"><?php echo hms_e($d['doctorName']); ?></option><?php } ?></select></div><div class="col-md-6"><input name="class_name" class="form-control" placeholder="Kelas perawatan"></div><div class="col-md-6"><button class="btn btn-success w-100">Buat Admission</button></div></form></div></div></div>
<div class="row g-3 mb-4"><div class="col-lg-6"><div class="hms-card p-3"><h2 class="h5">Check-out / Discharge</h2><form method="post" class="row g-2"><?php echo hms_csrf_field(); ?><input type="hidden" name="action" value="discharge"><div class="col-md-5"><select name="admission_id" class="form-select" required><option value="">Pilih pasien dirawat</option><?php foreach($adms as $a){ if($a['status']==='DIRAWAT'){ ?><option value="<?php echo (int)$a['id']; ?>"><?php echo hms_e($a['admission_no'].' - '.$a['PatientName']); ?></option><?php }} ?></select></div><div class="col-md-5"><input name="discharge_note" class="form-control" placeholder="Resume/discharge note"></div><div class="col-md-2"><button class="btn btn-warning w-100">Pulang</button></div></form></div></div><div class="col-lg-6"><div class="hms-card p-3"><h2 class="h5">Mutasi / Pindah Bed</h2><form method="post" class="row g-2"><?php echo hms_csrf_field(); ?><input type="hidden" name="action" value="transfer"><div class="col-md-5"><select name="admission_id" class="form-select" required><option value="">Pilih pasien</option><?php foreach($adms as $a){ if($a['status']==='DIRAWAT'){ ?><option value="<?php echo (int)$a['id']; ?>"><?php echo hms_e($a['admission_no'].' - '.$a['PatientName']); ?></option><?php }} ?></select></div><div class="col-md-5"><select name="new_bed_id" class="form-select" required><option value="">Bed baru</option><?php foreach($beds as $b){ if($b['status']==='TERSEDIA'){ ?><option value="<?php echo (int)$b['id']; ?>"><?php echo hms_e($b['ward'].' / '.$b['room_no'].'-'.$b['bed_no']); ?></option><?php }} ?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Pindah</button></div></form></div></div></div>
<div class="hms-card p-3 mb-4"><h2 class="h5">Daftar Bed</h2><div class="table-responsive"><table class="table"><thead><tr><th>Bangsal</th><th>Kamar</th><th>Bed</th><th>Kelas</th><th>Tarif</th><th>Status</th></tr></thead><tbody><?php foreach($beds as $b){ ?><tr><td><?php echo hms_e($b['ward']); ?></td><td><?php echo hms_e($b['room_no']); ?></td><td><?php echo hms_e($b['bed_no']); ?></td><td><?php echo hms_e($b['class_name']); ?></td><td><?php echo number_format($b['daily_rate'],2,',','.'); ?></td><td><?php echo hms_status_badge($b['status']); ?></td></tr><?php } ?></tbody></table></div></div>
<div class="hms-card p-3"><h2 class="h5">Pasien Rawat Inap</h2><div class="table-responsive"><table class="table"><thead><tr><th>Admission</th><th>Pasien</th><th>Bed</th><th>Dokter</th><th>Status</th><th>Masuk</th></tr></thead><tbody><?php foreach($adms as $a){ ?><tr><td><?php echo hms_e($a['admission_no']); ?></td><td><?php echo hms_e($a['PatientName']); ?></td><td><?php echo hms_e(($a['ward']??'').' '.($a['room_no']??'').'-'.($a['bed_no']??'')); ?></td><td><?php echo hms_e($a['doctorName']??'-'); ?></td><td><?php echo hms_status_badge($a['status']); ?></td><td><?php echo hms_e($a['admission_date']); ?></td></tr><?php } ?></tbody></table></div></div>
<?php hms_layout_footer(); ?>
